Multi-Agent Systems.code:
# Multi-agent system concept
class MultiAgentSystem:
    def __init__(self):
        self.agents = {}
        self.orchestrator = None

    def add_agent(self, name, role, capabilities):
        self.agents[name] = {
            "role": role,
            "capabilities": capabilities
        }

    def delegate_task(self, task):
        print(f"Orchestrator: Breaking down task: {task}")
        for name, agent in self.agents.items():
            print(f"  - Assigned to {name} ({agent['role']})")

system = MultiAgentSystem()
system.add_agent("Researcher", "information gatherer", ["web_search", "read_docs"])
system.add_agent("Coder", "code writer", ["write_code", "debug"])
system.add_agent("Reviewer", "quality assurance", ["code_review", "test"])
system.delegate_task("Build a web application")
